import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';
import '../services/app_state.dart';
import '../widgets/dedication_banner.dart';
class StatsScreen extends StatelessWidget{final AppState state;const StatsScreen({super.key,required this.state});@override Widget build(BuildContext c){final v=state.weekly();final maxY=(v.reduce((a,b)=>a>b?a:b)+2).toDouble();return Scaffold(appBar:AppBar(title:const Text('סטטיסטיקות')),body:Directionality(textDirection:TextDirection.rtl,child:ListView(padding:const EdgeInsets.all(12),children:[DedicationBanner(text:state.dedication),Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(children:[const Text('פרקים שנלמדו לפי ימי השבוע'),const SizedBox(height:220),SizedBox(height:220,child:BarChart(BarChartData(maxY:maxY,barGroups:[for(int i=0;i<7;i++)BarChartGroupData(x:i,barRods:[BarChartRodData(toY:v[i].toDouble(),width:18)])],titlesData:FlTitlesData(bottomTitles:AxisTitles(sideTitles:SideTitles(showTitles:true,getTitlesWidget:(x,m)=>Text(['א','ב','ג','ד','ה','ו','ש'][x.toInt()]))),leftTitles:const AxisTitles(sideTitles:SideTitles(showTitles:true)),topTitles:const AxisTitles(sideTitles:SideTitles(showTitles:false)),rightTitles:const AxisTitles(sideTitles:SideTitles(showTitles:false)))))]))]))));}}